import { readFileSync, readdirSync } from "node:fs";
import { parse } from "yaml";
import { z } from "zod";

const Effort = z.enum(["low", "medium", "high"]);

export const Charter = z.strictObject({
  name: z.string().regex(/^[a-z0-9-]+$/),
  team: z.enum(["fe", "be", "devops"]),
  stage: z.enum(["shadow", "drafts", "normal"]),
  trigger: z.looseObject({ kind: z.enum(["github.workflow_run", "jira", "schedule"]) }),
  gather_minutes: z.number().int().min(0).optional(),
  queue: z.enum(["cifix", "upgrade", "flaky", "bugfix", "health", "security"]),
  vm: z.strictObject({ size: z.enum(["lite", "full", "wide"]), spot: z.boolean().default(false) }),
  model: z.strictObject({ name: z.string(), effort: Effort, on_failed_checks: Effort.optional() }),
  allowed_paths: z.array(z.string()).min(1),
  denied_paths: z.array(z.string()).default([]),
  never: z.array(z.enum(["edit_test_assertions", "add_code", "add_retries_or_sleeps"])).default([]),
  skills: z.array(z.string()).min(1).max(6),
  done: z.array(z.string()).min(1),
});
export type Charter = z.infer<typeof Charter>;

export const parseCharter = (file: string, text: string): Charter => {
  const result = Charter.safeParse(parse(text));
  if (!result.success) throw new Error(`${file}\n${z.prettifyError(result.error)}`);
  if (`${result.data.name}.yaml` !== file) throw new Error(`${file}\n✖ name must match the file name`);
  return result.data;
};

export const loadCharters = (dir: string): Charter[] =>
  readdirSync(dir)
    .filter((f) => f.endsWith(".yaml"))
    .map((f) => parseCharter(f, readFileSync(`${dir}/${f}`, "utf8")));
EOF

