import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { loadCharters, parseCharter } from "../charter.ts";

const fe = readFileSync("charters/fe-ci-fixer.yaml", "utf8");

test("every charter in charters/ loads", () => {
  assert.ok(loadCharters("charters").length >= 2);
});

test("an unknown key is refused", () => {
  assert.throws(() => parseCharter("fe-ci-fixer.yaml", fe + "max_turns: 50\n"), /Unrecognized key: "max_turns"/);
});

test("a typo in denied_paths is refused, not dropped", () => {
  assert.throws(() => parseCharter("fe-ci-fixer.yaml", fe.replace("denied_paths:", "denied_path:")), /denied_path/);
});

test("seven skills are refused", () => {
  assert.throws(() => parseCharter("fe-ci-fixer.yaml", fe.replace("skills: [", "skills: [a, b, ")), /skills/);
});

test("the name must match the file", () => {
  assert.throws(() => parseCharter("fe-ci-fixer.yaml", fe.replace("name: fe-ci-fixer", "name: fe-fixer")), /file name/);
});
